d":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The OHLC series for the session, one candle per interval."},"is_debut":{"type":"boolean","description":"True on a listing day. Decides whether the reference line is the offer price or the prior close."},"reference_value":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The dashed reference line: the offer price on a debut, the prior close otherwise."},"reference_label":{"type":"string","minLength":1,"description":"Label for the reference line, e.g. `OFFER 27.00`."}},"required":["shape","caption","candles","is_debut","reference_value","reference_label"],"additionalProperties":false,"title":"BLK-CANDLE · Session candles","description":"One bound OHLC series. On a debut the reference line is the offer price, never a prior close — which is why the debut flag and the reference are both required."},"schema_version":1},{"key":"BLK-TIMELINE","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"stages":{"minItems":2,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"description":"Stage name."},"date":{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$","description":"Stage date, ISO `YYYY-MM-DD`."},"description":{"type":"string","minLength":1,"description":"One line on what happens at this stage."},"is_critical":{"type":"boolean","description":"Exactly one stage carries this. It is the one that costs money if missed."}},"required":["name","date","description","is_critical"],"additionalProperties":false},"description":"In date order. The renderer numbers them; the index is not a payload field."}},"required":["stages"],"additionalProperties":false,"title":"BLK-TIMELINE · Dates in order","description":"Stages left to right in date order. Exactly one stage is critical — the one that costs money if missed — and it is the only one in red."},"schema_version":1},{"key":"BLK-STEPS","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"steps":{"minItems":3,"maxItems":5,"type":"array","items":{"type":"object","properties":{"claim":{"type":"string","minLength":1,"description":"The step, stated as a claim. Set bold."},"clarification":{"type":"string","minLength":1,"description":"One clarifying line. Never a paragraph."}},"required":["claim","clarification"],"additionalProperties":false}}},"required":["steps"],"additionalProperties":false,"title":"BLK-STEPS · Numbered mechanism","description":"Three to five steps. Each is a bold claim plus one clarifying line — never a paragraph. Numbering comes from the order, not from the payload."},"schema_version":1},{"key":"BLK-FLOW","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"nodes":{"minItems":2,"maxItems":4,"type":"array","items":{"type":"object","properties":{"role":{"type":"string","minLength":1,"description":"Role label, e.g. `LENDER`, `OPCO`."},"name":{"type":"string","minLength":1,"description":"The entity."},"qualifier":{"type":"string","minLength":1,"description":"One qualifying line under the name."}},"required":["role","name","qualifier"],"additionalProperties":false}},"connectors":{"minItems":1,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"What flows along this arrow."},"seniority":{"type":"string","enum":["senior","subordinated"],"description":"Drives the arrow weight. Seniority, never size."},"value_label":{"type":"string","minLength":1,"description":"Amount or share, as printed."}},"required":["label","seniority","value_label"],"additionalProperties":false},"description":"Exactly one fewer than `nodes` — the chain never branches."},"equity_node_index":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"Zero-based index of the terminal equity node. Always the last node."}},"required":["nodes","connectors","equity_node_index"],"additionalProperties":false,"title":"BLK-FLOW · Money flow","description":"At most four nodes, left to right, never branching — a branch means the block is BLK-DECISION. Arrow weight shows seniority, not size. Equity is always the pale box at the end."},"schema_version":1},{"key":"BLK-ANATOMY","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"document_type":{"type":"string","minLength":1,"description":"What is being anatomised, e.g. `TADAWUL · CG-1`."},"regions":{"minItems":2,"type":"array","items":{"type":"object","properties":{"width_ratio":{"type":"number","exclusiveMinimum":0,"maximum":1,"description":"Region width as a fraction of the wireframe rail."},"highlight":{"type":"string","enum":["critical","secondary","boilerplate"],"description":"critical = the figure that changes your cash; secondary = the date block; boilerplate = skip it."}},"required":["width_ratio","highlight"],"additionalProperties":false}},"annotations":{"minItems":1,"type":"array","items":{"type":"object","properties":{"highlight":{"type":"string","enum":["critical","secondary","boilerplate"],"description":"Which region class this annotation''s swatch matches."},"title":{"type":"string","minLength":1,"description":"What this part of the document is."},"why_it_matters":{"type":"string","minLength":1,"description":"Why the reader should look at it."}},"required":["highlight","title","why_it_matters"],"additionalProperties":false}}},"required":["document_type","regions","annotations"],"additionalProperties":false,"title":"BLK-ANATOMY · Annotated document","description":"An abstracted wireframe, never a screenshot — it teaches where to look. Regions carry a semantic highlight class, not a colour, so the accent rule cannot be broken from the payload."},"schema_version":1},{"key":"BLK-WORKED","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"ticker":{"type":"string","minLength":1,"description":"A real ticker — the example is concrete or it does not teach."},"premise":{"type":"string","minLength":1,"description":"The premise header, e.g. `1,000 SHARES`."},"before":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Column header for the starting state."},"as_of":{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$","description":"The date the starting state is measured at."}},"required":["label","as_of"],"additionalProperties":false,"description":"The ''before'' column."},"after":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Column header for the ending state."},"as_of":{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$","description":"The date the ending state is measured at."}},"required":["label","as_of"],"additionalProperties":false,"description":"The ''after'' column — its header is ink because it carries the desk''s computation."},"rows":{"minItems":1,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1},"before_value":{"type":"number"},"after_value":{"type":"number"}},"required":["label","before_value","after_value"],"additionalProperties":false}},"total":{"type":"object","properties":{"label":{"default":"Total","type":"string","minLength":1},"before_value":{"type":"number"},"after_value":{"type":"number"}},"required":["before_value","after_value"],"additionalProperties":false,"description":"Mandatory. The row that settles the point."},"closing_sentence":{"type":"string","minLength":1,"description":"What the difference actually is, in words."}},"required":["ticker","premise","before","after","rows","total","closing_sentence"],"additionalProperties":false,"title":"BLK-WORKED · Worked example","description":"Round numbers on a real ticker. Deliberately illustrative, so the figures are literal — and it must end in a total row that settles the point."},"schema_version":1},{"key":"BLK-MYTH","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"assumption":{"type":"string","minLength":1,"description":"The assumption, in the reader''s own words. Set in italic serif."},"mechanism":{"type":"string","minLength":1,"description":"What actually happens, with the arithmetic."}},"required":["assumption","mechanism"],"additionalProperties":false,"title":"BLK-MYTH · Assumption vs mechanism","description":"The assumption stated in the reader''s own words, then the mechanism with the arithmetic. Never mock the assumption."},"schema_version":1},{"key":"BLK-DECISION","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"question":{"type":"string","minLength":1,"description":"The single question the reader is deciding."},"yes":{"type":"string","minLength":1,"description":"What follows if the answer is yes."},"no":{"type":"string","minLength":1,"description":"What follows if the answer is no."}},"required":["question","yes","no"],"additionalProperties":false,"title":"BLK-DECISION · If / then","description":"One question, two outcomes. The schema has no recursion, so a second level cannot be expressed at all — which is the rule, enforced structurally."},"schema_version":1},{"key":"BLK-GLOSSARY","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false,"title":"BLK-GLOSSARY · Terms on this page","description":"Auto-assembled in the rail from every BLK-TERM on the page, against the glossary store shared with Learn. A writer agent does not author this block — it emits BLK-TERM and this follows."},"schema_version":1},{"key":"BLK-TAPEROW","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"at":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$","description":"When the item happened. The renderer prints HH:MM in venue time."},"venue":{"type":"string","enum":["TDWL","ADX","DFM","QE","MSX","BHB","BK"]},"category":{"type":"string","minLength":1,"description":"Category chip, e.g. `DIVIDEND`, `RESULTS`. Rendered uppercase."},"ticker":{"type":"string","minLength":1},"filing_reference":{"type":"string","minLength":1,"description":"Filing reference, e.g. `CG-1`."},"headline":{"type":"string","minLength":1,"description":"The headline, set in serif."},"body":{"type":"string","pattern":"^\\s*(?:\\S+\\s+){0,39}\\S+\\s*$","description":"The item body. Max 40 words."}},"required":["at","venue","category","ticker","filing_reference","headline","body"],"additionalProperties":false,"title":"BLK-TAPEROW · Tape entry","description":"One item on the tape. Time in the gutter, venue under it. The body is capped at 40 words — that cap is what makes the item eligible for agent auto-publish."},"schema_version":1},{"key":"BLK-CHIPROW","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"chips":{"minItems":3,"maxItems":5,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Chip label."},"value":{"type":"string","minLength":1,"description":"Chip value, as printed."},"is_moving":{"default":false,"description":"The one chip that is the moving number. It takes the ink border.","type":"boolean"},"direction":{"description":"Required on the moving chip, forbidden on context chips.","type":"string","enum":["up","down"]}},"required":["label","value"],"additionalProperties":false}}},"required":["chips"],"additionalProperties":false,"title":"BLK-CHIPROW · Data chip row","description":"Three to five chips — the cheapest way to attach data to a 30-word item. At most one chip is the moving number; the rest are context and stay grey."},"schema_version":1},{"key":"BLK-SNAPSHOT","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"description":"What the series measures."},"series":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The bar series. Resolved and drawn by the chart compiler."},"labels":{"default":[],"description":"At most three labels — typically start period, peak, now.","maxItems":3,"type":"array","items":{"type":"string","minLength":1}}},"required":["title","series"],"additionalProperties":false,"title":"BLK-SNAPSHOT · Mini chart card","description":"The wire''s only permitted chart: one bound series, no axes, at most three labels. The peak and the latest bar are found in the resolved series, never asserted."},"schema_version":1},{"key":"BLK-COUNTDOWN","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"kicker":{"type":"string","minLength":1,"description":"What is closing, e.g. `RETAIL SUBSCRIPTION CLOSES`."},"deadline":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$","description":"The absolute deadline, with offset."},"timezone_label":{"type":"string","minLength":1,"description":"Timezone as printed beside the deadline, e.g. `GST`."},"context_line":{"type":"string","minLength":1,"description":"One line of context, e.g. the current cover level."},"cta_label":{"type":"string","minLength":1,"description":"CTA label. It routes the reader elsewhere — never to an order ticket."}},"required":["kicker","deadline","timezone_label","context_line","cta_label"],"additionalProperties":false,"title":"BLK-COUNTDOWN · Deadline clock","description":"The absolute deadline is the payload; the relative counter is rendered from it, never stored. Marsad never takes the order — the CTA sends the reader to their broker."},"schema_version":1},{"key":"BLK-HALT","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"status_chip":{"default":"HALTED","description":"Fixed house label — pinned to \"HALTED\" so a writer agent cannot reword it.","type":"string","const":"HALTED"},"ticker":{"type":"string","minLength":1},"halted_since":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},"expected_lift":{"anyOf":[{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$"},{"type":"null"}],"description":"Null when the lift time is not known — an indefinite halt is a state, not a gap."},"reason":{"type":"string","minLength":1,"description":"Why trading was halted."},"last_price":{"type":"number","description":"Last traded price before the halt."},"frozen_not_stale":{"type":"string","minLength":1,"description":"The explicit statement that the price is frozen rather than a stale feed. Required — this is the sentence a reader needs."}},"required":["ticker","halted_since","expected_lift","reason","last_price","frozen_not_stale"],"additionalProperties":false,"title":"BLK-HALT · Trading halt","description":"States the reason and the expected lift, and says in words whether the price is frozen or merely stale. An indefinite halt is expressed as a null lift time, never as a missing field."},"schema_version":1},{"key":"BLK-CORRECTION","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"chip":{"default":"REVISED","description":"Fixed house label — pinned to \"REVISED\" so a writer agent cannot reword it.","type":"string","const":"REVISED"},"published_at":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$","description":"When the original was published."},"corrected_at":{"type":"string","format":"date-time","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$","description":"When the correction was appended."},"corrected_object":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The lake object and field that was fixed. Every piece citing it is flagged; the right value renders from here."},"wrong_value":{"type":"string","minLength":1,"description":"The superseded value, as it was published. Literal — the lake no longer holds it."},"why_wrong":{"type":"string","minLength":1,"description":"What went wrong, naming the source that conflicted."},"remediation":{"type":"string","minLength":1,"description":"What was done to the lake object and to the downstream pieces."},"argument_survived":{"type":"boolean","description":"Whether the piece''s conclusion survives the correction. Required — never inferred, never omitted."},"rule_id":{"default":"R-07","type":"string","const":"R-07"}},"required":["published_at","corrected_at","corrected_object","wrong_value","why_wrong","remediation","argument_survived"],"additionalProperties":false,"title":"BLK-CORRECTION · Correction note","description":"Amber, never red — a correction is integrity. Appended, never silent. The corrected value is read from the fixed lake object; the wrong value is written down here because the lake no longer holds it."},"schema_version":1},{"key":"BLK-BREADTH","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"advancers":{"type":"integer","minimum":0,"maximum":9007199254740991},"decliners":{"type":"integer","minimum":0,"maximum":9007199254740991},"unchanged":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"The remainder bar."},"median_move_pct":{"type":"number","description":"Median move across the session, signed and in percent."},"best_performer":{"type":"object","properties":{"ticker":{"type":"string","minLength":1},"change_pct":{"type":"number"}},"required":["ticker","change_pct"],"additionalProperties":false},"value_traded":{"type":"string","minLength":1,"description":"Session value traded, as printed with its unit."}},"required":["advancers","decliners","unchanged","median_move_pct","best_performer","value_traded"],"additionalProperties":false,"title":"BLK-BREADTH · Session breadth","description":"Advancers, decliners and unchanged as a proportional bar, with the median move — which says whether the day was broad in a way the index cannot."},"schema_version":1},{"key":"BLK-VENUEHEAD","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"group_title":{"type":"string","minLength":1,"description":"Venue group title, e.g. `QATAR · KUWAIT · OMAN`."},"headline_index":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Index name, e.g. `QSI`."},"level":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."},"change_pct":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."}},"required":["label","level","change_pct"],"additionalProperties":false},"secondary_indices":{"default":[],"description":"Chips under the headline index.","type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1},"level":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."},"change_pct":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."}},"required":["label","level","change_pct"],"additionalProperties":false}},"venues":{"minItems":1,"type":"array","items":{"type":"object","properties":{"venue":{"type":"string","enum":["TDWL","ADX","DFM","QE","MSX","BHB","BK"]},"status":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."}},"required":["object_id"],"additionalProperties":false,"title":"Lake object reference","description":"The venue''s `market.status` object. Its state — live, delayed, offline — is read, never asserted."}},"required":["venue","status"],"additionalProperties":false}},"item_count":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"How many items this column carries on this page."}},"required":["group_title","headline_index","venues","item_count"],"additionalProperties":false,"title":"BLK-VENUEHEAD · Venue column header","description":"Groups a set of venues under one header and carries its own item count. Feed degradation is read from the bound market status per venue and named in the header — it is never a writer-supplied flag and never a footnote."},"schema_version":1},{"key":"BLK-PROV","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"object":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."}},"required":["object_id"],"additionalProperties":false,"title":"Lake object reference","description":"The object being stamped. Everything the stamp prints is read from it."}},"required":["object"],"additionalProperties":false,"title":"BLK-PROV · Lake object stamp","description":"Mandatory under every chart and table. The object type, entity, coverage depth, verifying agent, verification time, source class and verified/computed/pending status all render from the bound object — none of them is writer-supplied, because a stamp an agent can type is not a stamp."},"schema_version":1},{"key":"BLK-AGENTS","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"narrative":{"type":"string","minLength":1,"description":"How this piece was built, in a sentence or two."},"chain":{"minItems":2,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"description":"Agent id or person''s name."},"is_agent":{"type":"boolean","description":"Agents get the diamond; humans do not."}},"required":["name","is_agent"],"additionalProperties":false},"description":"In build order. The last entry is the human editor."}},"required":["narrative","chain"],"additionalProperties":false,"title":"BLK-AGENTS · How this was built","description":"The build chain, in order. Agent chips carry a diamond and humans do not — and the human is always last, which is checked rather than trusted."},"schema_version":1},{"key":"BLK-FRESH","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"venue":{"type":"string","enum":["TDWL","ADX","DFM","QE","MSX","BHB","BK"],"description":"Which venue''s feed this figure came from."},"status":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."}},"required":["object_id"],"additionalProperties":false,"title":"Lake object reference","description":"The venue''s `market.status` object. The badge reads its state and detail."}},"required":["venue","status"],"additionalProperties":false,"title":"BLK-FRESH · Freshness badge","description":"Every live figure carries one. The state — live, delayed, closed, feed offline — and its detail line resolve from the bound venue status at render time, through the reader app''s shared FreshnessBadge. Nothing about the feed is writer-asserted, because the writer cannot see it."},"schema_version":1},{"key":"BLK-ESTIMATE","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"actual":{"type":"object","properties":{"period_label":{"type":"string","minLength":1,"description":"Period of the filed figure, e.g. `FY25`."},"value":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The filed figure."}},"required":["period_label","value"],"additionalProperties":false,"description":"The company disclosure. Rendered muted."},"estimate":{"type":"object","properties":{"period_label":{"type":"string","minLength":1,"description":"Period of the estimate, e.g. `FY26`. The renderer appends the E suffix."},"value":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The desk computation."}},"required":["period_label","value"],"additionalProperties":false,"description":"The desk''s number. Rendered bold under an ink header."},"attribution":{"default":"MARSAD DESK","description":"Fixed house label — pinned to \"MARSAD DESK\" so a writer agent cannot reword it.","type":"string","const":"MARSAD DESK"},"footnote":{"type":"string","minLength":1,"description":"The statement that this is a desk computation, not a company disclosure."}},"required":["actual","estimate","footnote"],"additionalProperties":false,"title":"BLK-ESTIMATE · Desk-estimate marker","description":"Pairs a filed actual with a desk estimate so the two can be told apart. The renderer applies all three estimate signals at once; the payload carries no styling, so it cannot apply one of them instead."},"schema_version":1},{"key":"BLK-CONFLICT","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"figure_label":{"type":"string","minLength":1,"description":"What the withheld figure is."},"period_label":{"type":"string","minLength":1,"description":"Which period it covers."},"source_a":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Source name, e.g. `Vendor feed`."},"value":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."},"is_primary":{"type":"boolean","description":"Exactly one of the two sources is primary."}},"required":["label","value","is_primary"],"additionalProperties":false},"source_b":{"type":"object","properties":{"label":{"type":"string","minLength":1,"description":"Source name, e.g. `FY25 annual report`."},"value":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"D-8: a bound datum. The writer names the object and the field; the renderer reads the value at render time. Emitting a literal number here is a refusal."},"is_primary":{"type":"boolean"}},"required":["label","value","is_primary"],"additionalProperties":false},"resolution_statement":{"type":"string","minLength":1,"description":"That the figure is not quoted until the desk resolves it, and that primary wins unless overridden."}},"required":["figure_label","period_label","source_a","source_b","resolution_statement"],"additionalProperties":false,"title":"BLK-CONFLICT · Held from writers","description":"Sources disagree, so the figure is withheld: both values are shown, neither is picked. There is no field for a resolved value — publishing a gap beats publishing a guess."},"schema_version":1},{"key":"BLK-RULE","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"rule_id":{"type":"string","pattern":"^R-\\d{2}$","description":"Publishing-ruleset id, resolved against `ops.rules.rule_key` at the fit stage."},"requirement":{"type":"string","minLength":1,"description":"What the rule requires, in plain language."},"how_it_shaped_this":{"type":"string","minLength":1,"description":"How it shaped this specific piece."},"automated_check":{"type":"string","minLength":1,"description":"The automated check that enforces it, e.g. the screener flags payout > 100%."}},"required":["rule_id","requirement","how_it_shaped_this","automated_check"],"additionalProperties":false,"title":"BLK-RULE · Rule applied","description":"Used only when a rule visibly shaped the copy. Cites the id from the publishing ruleset — the reader learns the house standard by watching it get enforced."},"schema_version":1},{"key":"BLK-CUT","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"teaser":{"type":"string","minLength":1,"description":"The paragraph that blurs into the gradient. Must end on a complete thought."},"after_block_index":{"type":"integer","minimum":0,"maximum":9007199254740991,"description":"Zero-based index of the block the cut falls after, in the piece''s block sequence."},"data_blocks_before":{"type":"integer","minimum":1,"maximum":9007199254740991,"description":"How many data blocks (families C, D) render before the cut. At least one, always."},"rule_id":{"default":"R-09","type":"string","const":"R-09"}},"required":["teaser","after_block_index","data_blocks_before"],"additionalProperties":false,"title":"BLK-CUT · Premium cut","description":"Where the free read ends. It must fall after a complete thought and after at least one data block — the reader sees the work before the wall. The fit stage re-verifies both claims against the real block sequence."},"schema_version":1},{"key":"BLK-PAYWALL","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"kicker":{"default":"CONTINUE WITH PREMIUM","description":"Fixed house label — pinned to \"CONTINUE WITH PREMIUM\" so a writer agent cannot reword it.","type":"string","const":"CONTINUE WITH PREMIUM"},"behind_the_wall":{"type":"string","minLength":24,"description":"What specifically is behind the wall — the model, the table, the target. Generic copy is refused at the fit stage."},"cta_label":{"type":"string","minLength":1,"description":"Primary CTA label, e.g. `Start 14-day trial`."},"reassurance":{"type":"string","minLength":1,"description":"The reassurance line, e.g. `cancel anytime`."}},"required":["behind_the_wall","cta_label","reassurance"],"additionalProperties":false,"title":"BLK-PAYWALL · In-article paywall band","description":"Names the meter state and states specifically what is behind the wall — never a generic ''subscribe to read more''. The meter itself is per-request reader state and is resolved at render, so it is not a payload field."},"schema_version":1},{"key":"BLK-ALERTCTA","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"kicker":{"default":"KEEP WATCHING THIS","description":"Fixed house label — pinned to \"KEEP WATCHING THIS\" so a writer agent cannot reword it.","type":"string","const":"KEEP WATCHING THIS"},"headline":{"type":"string","minLength":1,"description":"What will trigger the ping."},"expected_event":{"type":"string","minLength":1,"description":"The event we expect, e.g. `Q3 results`."},"expected_date":{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$","description":"When we expect it."},"subject":{"type":"object","properties":{"entity":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."}},"required":["object_id"],"additionalProperties":false,"title":"Lake object reference","description":"The entity the piece is about."},"series":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."},"field":{"type":"string","minLength":1,"pattern":"^[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)*$","description":"Dotted path to the value on the lake object — `numeric_value`, `effective_date`, `payload.<key>`."}},"required":["object_id","field"],"additionalProperties":false,"title":"Lake object binding","description":"The tracked series the alert watches."},"condition":{"type":"string","minLength":1,"description":"The condition that fires the alert, e.g. `payout ratio above 100%`."}},"required":["entity","series","condition"],"additionalProperties":false,"description":"The pre-filled alert definition."},"cta_label":{"default":"Create alert →","description":"Fixed house label — pinned to \"Create alert →\" so a writer agent cannot reword it.","type":"string","const":"Create alert →"}},"required":["headline","expected_event","expected_date","subject"],"additionalProperties":false,"title":"BLK-ALERTCTA · Turn this into an alert","description":"Pre-fills the alert from the piece''s own subject — the reader must not re-specify it. The tracked series binds, so the alert watches the same object the piece argued about."},"schema_version":1},{"key":"BLK-DOWNLOAD","payload_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"kicker":{"default":"EVERY SERIES IS DOWNLOADABLE","description":"Fixed house label — pinned to \"EVERY SERIES IS DOWNLOADABLE\" so a writer agent cannot reword it.","type":"string","const":"EVERY SERIES IS DOWNLOADABLE"},"explanation":{"type":"string","minLength":1,"description":"Why this matters — the ids make the research auditable."},"format":{"default":"xlsx","description":"Fixed house label — pinned to \"xlsx\" so a writer agent cannot reword it.","type":"string","const":"xlsx"},"series":{"minItems":1,"type":"array","items":{"type":"object","properties":{"object_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$","description":"`lake.objects.id` — the object the renderer resolves this value from."}},"required":["object_id"],"additionalProperties":false,"title":"Lake object reference","description":"A lake object referenced as an object, not as a datum — its lineage, coverage, verifying agent and status are read from the row, never asserted by the writer."},"description":"Every lake object behind a series in the piece. The button''s count is this list''s length."}},"required":["explanation","series"],"additionalProperties":false,"title":"BLK-DOWNLOAD · Take the data","description":"Every series in the piece, shipped as .xlsx carrying the lake object ids so any figure traces back to its filing. The count is the length of the list, not a separate claim about it."},"schema_version":1}]'::jsonb)
         as s(key text, payload_schema jsonb, schema_version int)
 where b.key = s.key and b.status = 'active';

do $$
declare
  v_active int; v_filled int; v_legacy int; v_named int; v_bound int; v_missing text;
  c_bound text[] := array['BLK-ALERTCTA', 'BLK-AREA', 'BLK-BARS', 'BLK-BEATMISS', 'BLK-BIGNUM', 'BLK-CANDLE', 'BLK-CITE', 'BLK-COMPARE', 'BLK-CONFLICT', 'BLK-CORRECTION', 'BLK-COVER', 'BLK-DIST', 'BLK-DONUT', 'BLK-DOWNLOAD', 'BLK-DUMBBELL', 'BLK-ESTIMATE', 'BLK-EXDATE', 'BLK-FINTABLE', 'BLK-FRESH', 'BLK-HEAT', 'BLK-INDEXED', 'BLK-KEYSTATS', 'BLK-LINE', 'BLK-PROV', 'BLK-RANGE', 'BLK-RANKROW', 'BLK-SCATTER', 'BLK-SCENARIO', 'BLK-SLOPE', 'BLK-SNAPSHOT', 'BLK-SPARK', 'BLK-STACK', 'BLK-STATSTRIP', 'BLK-TICKER', 'BLK-VENUEHEAD', 'BLK-WATERFALL'];
begin
  select count(*) into v_active from ops.story_blocks where status = 'active';
  if v_active <> 61 then raise exception 'expected 61 active blocks, got %', v_active; end if;

  -- (1) every active block has a payload schema; PD.3 is not partially applied
  select count(*) into v_filled from ops.story_blocks where status = 'active' and payload_schema is not null;
  if v_filled <> 61 then
    select string_agg(key, ', ' order by key) into v_missing
      from ops.story_blocks where status = 'active' and payload_schema is null;
    raise exception 'blocks without a payload_schema: %', v_missing;
  end if;

  -- (2) the legacy vocabulary stays schema-less on purpose — the design SPLITS those keys
  --     (BLK-CHART became 15 shapes), so there is no payload contract to state for them
  select count(*) into v_legacy from ops.story_blocks where status = 'legacy' and payload_schema is not null;
  if v_legacy <> 0 then raise exception '% legacy blocks were given a payload_schema', v_legacy; end if;

  -- (3) each schema is named after its own block, so a validation error names the block
  select count(*) into v_named from ops.story_blocks
   where status = 'active' and payload_schema->>'title' like key || ' · %';
  if v_named <> 61 then raise exception 'only % of 61 schemas are named after their block', v_named; end if;

  -- (4) D-8, asserted: every block whose schema carries an object binding is exactly the set the
  --     generator computed, so the registry and the schemas cannot drift apart silently.
  --     Same predicate as carriesObjectBinding() in ingestion/src/blocks/index.ts: an object
  --     type whose properties include object_id, at any depth.
  select count(*) into v_bound from ops.story_blocks
   where status = 'active' and key = any(c_bound)
     and jsonb_path_exists(payload_schema, '$.**.properties.object_id');
  if v_bound <> array_length(c_bound, 1) then
    raise exception 'expected % bound blocks, matched %', array_length(c_bound, 1), v_bound;
  end if;

  raise notice 'story_blocks.payload_schema: % schemas, % of them bound', v_filled, v_bound;
end $$;
